 schema={'@context':'https://schema.org','@type':'CollectionPage','name':title,'url':'https://matveyshemyakin.ru'+path,'inLanguage':lang,'dateModified':'2026-11-17','mainEntity':{'@type':'ItemList','numberOfItems':len(DATA),'itemListElement':[{'@type':'ListItem','position':i+1,'name':d['title'],'url':('https://matveyshemyakin.ru'+prefix+d['url'] if d['url'].startswith('/') else d['url'])} for i,d in enumerate(DATA)]}}
 base=base.replace('</head>','<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script><link rel="stylesheet" href="/assets/cabinet/cabinet.css?v=20261117-1"></head>')
